459→/**
460→ * Build the body content for a section based on its type.
461→ */
462→function _buildSectionBody(sec) {
463→  const container = document.createDocumentFragment();
464→
465→  switch (sec.type) {
466→    case "flow_chain": {
467→      const chains = sec.data.chains || [sec.data];
468→      for (const chainData of chains) {
469→        const nodes = (chainData.nodes || []).map(n =>
470→          typeof n === "string" ? { label: n, slotType: "model" } : n
471→        );
472→        container.appendChild(createFlowChain(nodes, chainData.label));
473→      }
474→      break;
475→    }
476→
477→    case "slot_tags": {
478→      const wrap = document.createElement("div");
