 50→class AgentConnection {
 51→  constructor(onMessage, onStatus) {
 52→    this.ws = null;
 53→    this.onMessage = onMessage;   // (event) => void
 54→    this.onStatus = onStatus;     // (status) => void
 55→    this.reconnectDelay = 1000;
 56→    this.maxReconnectDelay = 15000;
 57→    this.currentDelay = this.reconnectDelay;
 58→    this._closed = false;
 59→  }
 60→
 61→  connect() {
 62→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
 63→    const url = `${proto}//${location.host}/superduper/ws`;
 64→
 65→    this.onStatus("connecting");
 66→    this.ws = new WebSocket(url);
 67→
 68→    this.ws.onopen = () => {
 69→      this.currentDelay = this.reconnectDelay;
 70→      this.onStatus("connected");
 71→    };
 72→
 73→    this.ws.onmessage = (evt) => {
 74→      try {
 75→        const data = JSON.parse(evt.data);
 76→        this.onMessage(data);
 77→      } catch (e) {
 78→        console.error("[SUPER DUPER] Bad message:", evt.data);
 79→      }
 80→    };
 81→
 82→    this.ws.onclose = () => {
 83→      this.onStatus("disconnected");
 84→      if (!this._closed) {
 85→        setTimeout(() => this.connect(), this.currentDelay);
 86→        this.currentDelay = Math.min(this.currentDelay * 1.5, this.maxReconnectDelay);
 87→      }
 88→    };
 89→
 90→    this.ws.onerror = (err) => {
 91→      console.error("[SUPER DUPER] WebSocket error:", err);
 92→    };
 93→  }
 94→
 95→  send(type, payload) {
 96→    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
 97→      this.ws.send(JSON.stringify({ type, ...payload }));
 98→      return true;
 99→    }
100→    return false;
101→  }
102→
103→  close() {
104→    this._closed = true;
105→    if (this.ws) this.ws.close();
106→  }
