110→
111→function buildSidebar(el) {
112→  el.style.height = "100%";
113→  el.style.display = "flex";
114→  el.style.flexDirection = "column";
115→
116→  el.innerHTML = `
117→    <div class="sd-header">
118→      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
119→      <span class="sd-header__status" id="sd-status"></span>
120→    </div>
121→    <div class="sd-stage-bar" id="sd-stage" style="display:none">
122→      <span class="sd-stage__label" id="sd-stage-label"></span>
123→      <span class="sd-stage__detail" id="sd-stage-detail"></span>
124→    </div>
125→    <div class="sd-messages" id="sd-messages" role="log" aria-live="polite" aria-label="Chat with Super Duper AI">
126→      <div class="sd-message sd-message--system">
127→        <span class="sd-message__body">What would you like to do with your workflow?</span>
128→      </div>
129→    </div>
130→    <div class="sd-input-bar">
131→      <input
132→        type="text"
133→        id="sd-input"
134→        class="sd-input"
135→        placeholder="Ask me anything about your workflow..."
136→        autocomplete="off"
137→      />
138→      <button id="sd-send" class="sd-send-btn" aria-label="Send message">Send</button>
139→    </div>
140→  `;
141→
142→  const messagesEl = el.querySelector("#sd-messages");
143→  const inputEl = el.querySelector("#sd-input");
144→  const sendBtn = el.querySelector("#sd-send");
145→  const statusEl = el.querySelector("#sd-status");
146→  const stageBar = el.querySelector("#sd-stage");
147→  const stageLabel = el.querySelector("#sd-stage-label");
148→  const stageDetail = el.querySelector("#sd-stage-detail");
149→
150→  let busy = false;
151→  let streamingEl = null;     // element receiving streamed text deltas
152→  let streamAccum = "";       // accumulated text during streaming
153→  let typingIndicator = null; // typing dots shown during stream
154→
155→  function scrollToBottom() {
156→    messagesEl.scrollTop = messagesEl.scrollHeight;
157→  }
158→
159→  function setStage(stage, detail, nodesTouched) {
160→    if (stage === "DONE" || !stage) {
161→      stageBar.style.display = "none";
162→      return;
163→    }
164→    stageBar.style.display = "flex";
165→    stageLabel.textContent = stage;
166→    stageDetail.textContent = detail || "";
167→
168→    // Remove existing pills
169→    const existingPills = stageBar.querySelectorAll(".sd-node-pill");
170→    existingPills.forEach(p => p.remove());
171→
172→    // Render node pills if provided
173→    if (nodesTouched && nodesTouched.length > 0) {
174→      for (const node of nodesTouched) {
175→        const pill = createNodePill(
176→          node.class_type,
177→          node.slot_type,
178→          node.node_id
179→        );
180→        stageBar.appendChild(pill);
181→      }
182→    }
183→  }
184→
185→  function setBusy(state) {
186→    busy = state;
187→    sendBtn.disabled = state;
188→    inputEl.disabled = state;
189→    sendBtn.textContent = state ? "..." : "Send";
190→  }
191→
192→  /* ── WebSocket message handler ────────────────────────────────── */
193→
194→  function handleAgentMessage(data) {
195→    switch (data.type) {
196→      case "connected":
197→        break;
198→
199→      case "text_delta":
200→        // Streaming: show typing indicator, accumulate text
201→        if (!streamingEl) {
202→          streamingEl = document.createElement("div");
203→          streamingEl.className = "sd-message sd-message--agent";
204→
205→          const label = document.createElement("span");
206→          label.className = "sd-message__label";
207→          label.textContent = "Agent";
208→          streamingEl.appendChild(label);
209→
210→          const body = document.createElement("div");
211→          body.className = "sd-message__body sd-text-body";
212→          streamingEl.appendChild(body);
213→
214→          messagesEl.appendChild(streamingEl);
215→          streamAccum = "";
216→        }
217→
218→        streamAccum += data.text;
219→
220→        // Show typing indicator during streaming
221→        const streamBody = streamingEl.querySelector(".sd-message__body");
222→        if (!typingIndicator) {
223→          typingIndicator = createTypingIndicator();
224→          streamBody.appendChild(typingIndicator);
225→        }
226→
227→        scrollToBottom();
228→        break;
229→
230→      case "message": {
231→        // Full message — render with rich text, replacing streaming element
232→        const finalText = data.content || streamAccum;
233→
234→        if (streamingEl) {
235→          // Replace streaming content with final rendered text
236→          const body = streamingEl.querySelector(".sd-message__body");
237→          body.textContent = ""; // clear typing indicator
238→          body.classList.add("sd-text-body");
239→          body.appendChild(renderText(finalText));
240→          streamingEl = null;
241→          streamAccum = "";
242→          typingIndicator = null;
243→        } else {
244→          messagesEl.appendChild(createMessageEl("agent", finalText));
245→        }
246→        scrollToBottom();
247→        break;
248→      }
249→
250→      case "panel": {
251→        // Structured panel from tool result
252→        const panelEl = createPanel(data.panel);
253→        if (panelEl) {
254→          // Wrap in a message container for consistent spacing
255→          const wrapper = document.createElement("div");
256→          wrapper.className = "sd-message sd-message--agent";
257→          wrapper.style.padding = "0";
258→          wrapper.style.background = "none";
259→          wrapper.appendChild(panelEl);
260→          messagesEl.appendChild(wrapper);
261→          scrollToBottom();
262→        }
263→        break;
264→      }
265→
266→      case "stage":
267→        setStage(data.stage, data.detail, data.nodes_touched);
268→
269→        // Show node interaction indicator in chat
270→        if (data.nodes_touched && data.nodes_touched.length > 0 && data.stage !== "DONE") {
271→          const nodeMsg = document.createElement("div");
272→          nodeMsg.className = "sd-message sd-message--node-activity";
273→
274→          const activityLabel = document.createElement("span");
275→          activityLabel.className = "sd-node-activity__label";
276→          activityLabel.textContent = data.stage === "PILOT" ? "Modifying" : "Inspecting";
277→          nodeMsg.appendChild(activityLabel);
278→
279→          for (const node of data.nodes_touched) {
280→            const pill = createNodePill(
281→              node.class_type,
282→              node.slot_type,
283→              node.node_id
284→            );
285→            nodeMsg.appendChild(pill);
286→          }
287→
288→          messagesEl.appendChild(nodeMsg);
289→          scrollToBottom();
290→        }
291→
292→        if (data.stage === "DONE") {
293→          // Clean up streaming state
294→          if (streamingEl && streamAccum) {
295→            const body = streamingEl.querySelector(".sd-message__body");
296→            body.textContent = "";
297→            body.classList.add("sd-text-body");
298→            body.appendChild(renderText(streamAccum));
299→          }
300→          streamingEl = null;
301→          streamAccum = "";
302→          typingIndicator = null;
303→          setBusy(false);
304→        }
305→        break;
306→
307→      case "error":
308→        setStage(null);
309→        messagesEl.appendChild(createMessageEl("system", data.message));
310→        streamingEl = null;
311→        streamAccum = "";
312→        typingIndicator = null;
313→        setBusy(false);
314→        scrollToBottom();
315→        break;
316→
317→      default:
318→        console.log("[SUPER DUPER] Unknown event:", data);
319→    }
320→  }
321→
322→  function handleStatus(status) {
323→    statusEl.textContent = status === "connected" ? "" : status;
324→    statusEl.className = `sd-header__status sd-header__status--${status}`;
325→  }
326→
327→  /* ── Connect ──────────────────────────────────────────────────── */
328→
329→  const conn = new AgentConnection(handleAgentMessage, handleStatus);
330→  conn.connect();
331→
332→  /* ── Send message ─────────────────────────────────────────────── */
333→
334→  async function sendMessage() {
335→    const text = inputEl.value.trim();
336→    if (!text || busy) return;
337→
338→    // Show user message
339→    messagesEl.appendChild(createMessageEl("user", text));
340→    inputEl.value = "";
341→    scrollToBottom();
342→
343→    // Capture current workflow from ComfyUI canvas
344→    let workflow = null;
345→    try {
346→      const result = await app.graphToPrompt();
347→      if (result && result.output) {
348→        workflow = result.output;
349→      }
350→    } catch (e) {
351→      console.warn("[SUPER DUPER] Could not capture workflow:", e);
352→    }
353→
354→    // Send to agent via WebSocket (include workflow if captured)
355→    const payload = { content: text };
356→    if (workflow) {
357→      payload.workflow = workflow;
358→    }
359→    const sent = conn.send("chat", payload);
360→    if (!sent) {
361→      messagesEl.appendChild(
362→        createMessageEl("system", "Not connected. Reconnecting...")
363→      );
364→      scrollToBottom();
365→      return;
366→    }
367→
368→    setBusy(true);
369→  }
370→
371→  sendBtn.addEventListener("click", sendMessage);
372→
373→  // Node pill canvas interaction (event delegation)
374→  messagesEl.addEventListener("click", (e) => {
375→    const pill = e.target.closest(".sd-node-pill");
376→    if (!pill || !pill.dataset.nodeId) return;
377→
378→    try {
379→      const graph = app.graph;
380→      if (graph) {
381→        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
382→        if (node) {
383→          app.canvas.deselectAllNodes();
384→          app.canvas.selectNode(node);
385→          app.canvas.centerOnNode(node);
386→        }
387→      }
388→    } catch (err) {
389→      console.warn("[Super Duper] Could not highlight node:", err);
390→    }
391→  });
392→
393→  // Node pill hover highlighting
394→  messagesEl.addEventListener("mouseenter", (e) => {
395→    const pill = e.target.closest(".sd-node-pill");
396→    if (!pill || !pill.dataset.nodeId) return;
397→
398→    try {
399→      const graph = app.graph;
400→      if (graph) {
401→        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
402→        if (node) {
403→          node._sd_orig_color = node.color;
404→          const color = getComputedStyle(pill).getPropertyValue("--pill-color").trim();
405→          node.color = color;
406→          app.canvas.setDirty(true, true);
407→        }
408→      }
409→    } catch (err) { /* silent */ }
410→  }, true);
411→
412→  messagesEl.addEventListener("mouseleave", (e) => {
413→    const pill = e.target.closest(".sd-node-pill");
414→    if (!pill || !pill.dataset.nodeId) return;
415→
416→    try {
417→      const graph = app.graph;
418→      if (graph) {
419→        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
420→        if (node && node._sd_orig_color !== undefined) {
421→          node.color = node._sd_orig_color;
422→          delete node._sd_orig_color;
423→          app.canvas.setDirty(true, true);
424→        }
425→      }
426→    } catch (err) { /* silent */ }
427→  }, true);
428→
429→  inputEl.addEventListener("keydown", (e) => {
430→    if (e.key === "Enter" && !e.shiftKey) {
431→      e.preventDefault();
432→      sendMessage();
433→    }
434→  });
435→
436→  setTimeout(() => inputEl.focus(), 100);
437→}
